/// <summary>
/// Find by reference
/// </summary>
/// <param name = "_hmimItemMaterialRecID">_hmimItemMaterialRecID</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>HMIMItemMaterial</returns>
static public METHMIMItemMaterial find(RefRecId _hmimItemMaterialRecID, boolean _forUpdate = false)
{
    METHMIMItemMaterial metHMIMItemMaterial;
    if(_hmimItemMaterialRecID)
    {
        metHMIMItemMaterial.selectForUpdate(_forUpdate);
        select firstonly metHMIMItemMaterial
           where   metHMIMItemMaterial.RefRecId == _hmimItemMaterialRecID;
    }
    return metHMIMItemMaterial;
}

    /// <summary>
    /// Lookup method for EMSCodeSpillageSchedId.
    /// </summary>
    public void lookupEMSCodeSpillageSchedId(FormStringControl _control)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbds;
        SysTableLookup          sysTableLookup;

        sysTableLookup  = sysTableLookup::newParameters(tableNum(MetEMSCodeSpillageSchedule), _control);
        sysTableLookup.addLookupField(fieldnum(MetEMSCodeSpillageSchedule, EMSCodeSpillageScheduleId));
        sysTableLookup.addLookupField(fieldnum(MetEMSCodeSpillageSchedule, Description));
        qbds = query.addDataSource(tableNum(MetEMSCodeSpillageSchedule));
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
    }

    /// <summary>
    /// Validates whether the subsidiary hazard field values are stored under division table.
    /// </summary>
    /// <returns>A boolean value either true or false.</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (!this.validateSelectedNotes(this.SubsideryHazard))
        {
            ret = false;
        }
    
        return ret;
    }

    /// <summary>
    /// Validates the input values available on division table or not.
    /// </summary>
    /// <param name = "_noteStr">_noteStr</param>
    /// <returns>A boolean value either true or false.</returns>
    private boolean validateSelectedNotes(METSubsideryHazard _noteStr)
    {
        HMIMDivision hmimDivision;
        container tmpValues, conIds, conName;
        int idx;
        boolean ret = true;

        if (_noteStr)
        {
            tmpValues = str2con(_noteStr, METConstants::AddressSeperator);
        }

        for (idx = 1; idx <= conLen(tmpValues); idx++)
        {
            hmimDivision = HMIMDivision::find(conPeek(tmpValues, idx));

            if (!hmimDivision.RecId)
            {
                ret = checkFailed(strFmt("@MET:ValidateDivision", conPeek(tmpValues, idx), fieldStr(METHMIMItemMaterial, SubsideryHazard), tableStr(HMIMDivision)));
            }
        }

        return ret;
    }
